INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2036ROA', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $PQR$, point $S$ lies on $\\overline{PQ}$ and point $T$ lies on $\\overline{QR}$ such that $\\overline{ST}$ is parallel to $\\overline{PR}$. If $QS = 14$, $SP = 21$, and $ST = 18$, what is the length of $\\overline{PR}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '45', ARRAY['45'], E'Since $\\overline{ST}$ is parallel to $\\overline{PR}$, triangles $QST$ and $QPR$ are similar by the AA similarity criterion. The ratio of corresponding sides equals $\\frac{QS}{QP} = \\frac{14}{14 + 21} = \\frac{14}{35} = \\frac{2}{5}$. Therefore $\\frac{ST}{PR} = \\frac{2}{5}$, which gives $PR = 18 \\times \\frac{5}{2} = 45$. A common error is using the ratio $\\frac{QS}{SP} = \\frac{14}{21} = \\frac{2}{3}$ instead of $\\frac{QS}{QP} = \\frac{2}{5}$, which would incorrectly yield $PR = 18 \\times \\frac{3}{2} = 27$. Another error is applying the ratio in the wrong direction, computing $18 \\times \\frac{2}{5} = 7.2$ instead of dividing.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20IIMWG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A rectangular prism has a square base with side length $14$ cm and a height of $21$ cm. A square pyramid with the same base (side length $14$ cm) and a height of $9$ cm is removed from the top of the prism. What is the volume of the remaining solid, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$588$"},{"key":"B","text":"$2352$"},{"key":"C","text":"$3528$"},{"key":"D","text":"$4116$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct volume is $3528$ cubic centimeters. The volume of the rectangular prism is $14^2 \\times 21 = 196 \\times 21 = 4116$ cubic centimeters. The volume of the square pyramid is $\\frac{1}{3} \\times 14^2 \\times 9 = \\frac{1}{3}(196)(9) = \\frac{1764}{3} = 588$ cubic centimeters. The remaining solid has volume $4116 - 588 = 3528$. The value $588$ results from reporting the pyramid volume that was removed rather than the volume of the remaining solid, misreading what the question asks. The value $2352$ comes from computing $4116 - 196 \\times 9 = 4116 - 1764 = 2352$, using $\\text{base} \\times \\text{height}$ for the pyramid volume instead of $\\frac{1}{3} \\times \\text{base} \\times \\text{height}$. The value $4116$ results from computing the full prism volume without subtracting the removed pyramid.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22E7YKS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cone has a base radius of $6$ cm and a height of $11$ cm. What is the volume of the cone?', NULL, $lyceon_json$[{"key":"A","text":"$44\\pi \\text{ cm}^3$"},{"key":"B","text":"$132\\pi \\text{ cm}^3$"},{"key":"C","text":"$264\\pi \\text{ cm}^3$"},{"key":"D","text":"$396\\pi \\text{ cm}^3$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct volume is $132\\pi$ cubic centimeters. The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(6)^2(11) = \\frac{1}{3}\\pi(36)(11) = \\frac{396\\pi}{3} = 132\\pi$. The value $44\\pi$ results from an arithmetic slip, such as dividing $396$ by $9$ instead of $3$, or miscomputing $\\frac{1}{3}(36)(11)$ as $\\frac{1}{3}(132) = 44$. The value $264\\pi$ results from using the factor $\\frac{2}{3}$ instead of $\\frac{1}{3}$, confusing the cone volume formula with the hemisphere volume formula. The value $396\\pi$ results from computing $\\pi r^2 h = \\pi(36)(11) = 396\\pi$ without applying the $\\frac{1}{3}$ factor, which gives the volume of a cylinder rather than a cone.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25L8OZJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'At a community center, $71$ participants each signed up for exactly one of three workshops: calligraphy, ceramics, or woodworking. There are $29$ participants in calligraphy, $26$ in ceramics, and $16$ in woodworking. Of the calligraphy participants, $13$ have prior experience. Of the ceramics participants, $9$ have prior experience. Of the woodworking participants, $7$ have prior experience. A participant is selected at random. Given that the selected participant has no prior experience, what is the probability that this participant signed up for ceramics? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17/42', ARRAY['17/42', '0.404', '.404', '0.405', '.405'], E'The total number of participants with prior experience is $13 + 9 + 7 = 29$, so the number without prior experience is $71 - 29 = 42$. The number of ceramics participants without prior experience is $26 - 9 = 17$. The conditional probability is $\\frac{17}{42}$. A common error is to compute $\\frac{26}{71}$, the unconditional probability of choosing ceramics without restricting to those with no prior experience. Another error is to find the correct numerator of $17$ but divide by $71$ rather than $42$, yielding $\\frac{17}{71}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM264O5P9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university randomly selects $380$ students from its enrollment and records each student''s weekly hours of physical exercise and their cumulative grade point average. The university finds that students who exercise more than $7$ hours per week have higher average GPAs than students who exercise fewer than $2$ hours per week. Which of the following conclusions is best supported by this study design?', NULL, $lyceon_json$[{"key":"A","text":"Increasing physical exercise causes higher GPAs among students at this university."},{"key":"B","text":"There is an association between weekly exercise hours and GPA among students at this university."},{"key":"C","text":"There is an association between weekly exercise hours and GPA among all university students nationwide."},{"key":"D","text":"Exercising more than $7$ hours per week causes higher GPAs among all university students."}]$lyceon_json$::jsonb, 'B', NULL, E'This is an observational study because exercise hours were not randomly assigned to students. Without random assignment, the study can establish an association but not causation. Since the sample was randomly selected from this university''s enrollment, the finding generalizes to students at this university but not to all university students nationwide. The claim that increasing exercise causes higher GPAs incorrectly infers causation from an observational design. The claim of association among all university students nationwide correctly avoids causation but overgeneralizes beyond the university from which the sample was drawn. The claim that exercising more than $7$ hours causes higher GPAs among all university students both infers causation and overgeneralizes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26JYURV', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 + 3x - 40}{x^2 - 13x + 40} \\cdot \\frac{x^2 - 3x - 40}{x^2 + 13x + 40}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{(x + 8)(x - 8)}{(x + 5)(x - 5)}$"},{"key":"B","text":"$\\frac{x^2 - 40}{x^2 + 40}$"},{"key":"C","text":"$1$"},{"key":"D","text":"$\\frac{(x - 5)(x + 5)}{(x - 8)(x + 8)}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Factor each quadratic: $x^2 + 3x - 40 = (x + 8)(x - 5)$, $x^2 - 13x + 40 = (x - 5)(x - 8)$, $x^2 - 3x - 40 = (x - 8)(x + 5)$, and $x^2 + 13x + 40 = (x + 5)(x + 8)$. The product becomes $\\frac{(x + 8)(x - 5)}{(x - 5)(x - 8)} \\cdot \\frac{(x - 8)(x + 5)}{(x + 5)(x + 8)}$. In the first fraction, $(x - 5)$ cancels, leaving $\\frac{x + 8}{x - 8}$. In the second fraction, $(x + 5)$ cancels, leaving $\\frac{x - 8}{x + 8}$. Multiplying $\\frac{x + 8}{x - 8} \\cdot \\frac{x - 8}{x + 8} = 1$. The distractor $\\frac{(x + 8)(x - 8)}{(x + 5)(x - 5)}$ comes from partial reasoning, cancelling only the matching linear factors but leaving behind the wrong remaining factors in an unsimplified form. The distractor $\\frac{x^2 - 40}{x^2 + 40}$ results from incorrectly combining terms rather than factoring, treating the constant terms as separable from the quadratic structure. The distractor $\\frac{(x - 5)(x + 5)}{(x - 8)(x + 8)}$ results from a sign error in tracking which factors belong in the numerator versus denominator after partial cancellation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM271Y5TN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. Two consecutive interior angles (co-interior angles) on the same side of the transversal measure $(5x + 17)^\\circ$ and $(3x + 11)^\\circ$. What is the measure of the larger angle?', NULL, $lyceon_json$[{"key":"A","text":"$19^\\circ$"},{"key":"B","text":"$68^\\circ$"},{"key":"C","text":"$95^\\circ$"},{"key":"D","text":"$112^\\circ$"}]$lyceon_json$::jsonb, 'D', NULL, E'Co-interior angles formed by parallel lines and a transversal are supplementary, so $(5x + 17) + (3x + 11) = 180$. Simplifying gives $8x + 28 = 180$, so $8x = 152$ and $x = 19$. The larger angle is $5(19) + 17 = 95 + 17 = 112^\\circ$. The value $19^\\circ$ results from reporting the value of $x$ itself rather than substituting back to find the angle measure. The value $68^\\circ$ comes from correctly finding $x = 19$ but computing the smaller angle $3(19) + 11 = 68$ instead of the larger one. The value $95^\\circ$ results from an arithmetic slip: computing $5(19) = 95$ but neglecting to add the constant $17$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27V77EF', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What value of $x$ satisfies the equation $$4(5x + 3) - 7(2x - 9) = 12 - 3x\\;?$$', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$7$"},{"key":"D","text":"$-63$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing gives $20x + 12 - 14x + 63 = 12 - 3x$. Combining like terms on the left yields $6x + 75 = 12 - 3x$. Adding $3x$ to both sides gives $9x + 75 = 12$. Subtracting $75$ from both sides gives $9x = -63$, so $x = -7$. The value $-9$ results from an arithmetic slip where the solver finds $9x = -63$ but divides by $7$ instead of $9$. The value $7$ arises from a sign error, dropping the negative from the correct answer. The value $-63$ comes from finding $9x = -63$ and reporting $-63$ without dividing by $9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27XSI5K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A concrete mix requires $9$ parts gravel and $4$ parts sand by weight. Gravel costs $1.70$ dollars per kilogram and sand costs $2.90$ dollars per kilogram. What is the cost, in dollars per kilogram, of the concrete mix?', NULL, $lyceon_json$[{"key":"A","text":"$2.07$"},{"key":"B","text":"$2.30$"},{"key":"C","text":"$4.60$"},{"key":"D","text":"$2.90$"}]$lyceon_json$::jsonb, 'A', NULL, E'In $13$ kilograms of mix ($9 + 4$), the cost of gravel is $9 \\times 1.70 = 15.30$ dollars and the cost of sand is $4 \\times 2.90 = 11.60$ dollars. The total cost is $15.30 + 11.60 = 26.90$ dollars for $13$ kilograms, so the cost per kilogram is $\\frac{26.90}{13} \\approx 2.07$ dollars. The value $2.30$ results from taking the simple average $\\frac{1.70 + 2.90}{2} = 2.30$ instead of using the weighted average based on the weight ratio. The value $4.60$ comes from adding the two unit prices $1.70 + 2.90 = 4.60$ without weighting or dividing by the total weight. The value $2.90$ ignores the gravel entirely and uses only the sand cost.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28HKD7T', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'The equation $x^2 + y^2 - 22x + 12y - 243 = 0$ defines a circle in the $xy$-plane. What is the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{157}$"},{"key":"B","text":"$\\sqrt{243}$"},{"key":"C","text":"$20$"},{"key":"D","text":"$400$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct radius is $20$. Completing the square: group the $x$-terms and $y$-terms as $(x^2 - 22x) + (y^2 + 12y) = 243$. Completing the square for $x$: $(x^2 - 22x + 121) = (x - 11)^2$ adds $121$. For $y$: $(y^2 + 12y + 36) = (y + 6)^2$ adds $36$. So $(x - 11)^2 + (y + 6)^2 = 243 + 121 + 36 = 400$, giving $r^2 = 400$ and $r = 20$. The value $\\sqrt{157}$ comes from computing $\\sqrt{121 + 36} = \\sqrt{157}$, adding the completing-the-square constants as though they alone determine $r^2$ without the original constant. The value $\\sqrt{243}$ results from taking the square root of the absolute value of the original constant term without completing the square. The value $400$ results from finding $r^2 = 400$ but reporting that value without taking the square root to obtain $r$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28XTRBU', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ is defined by the equation $3x - 4y = 20$. Line $q$ is perpendicular to line $p$ and passes through the point $(6, -3)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$-11$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$5$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewriting line $p$ in slope-intercept form: $3x - 4y = 20$ becomes $y = \\frac{3}{4}x - 5$, so the slope of line $p$ is $\\frac{3}{4}$. A line perpendicular to $p$ has slope $-\\frac{4}{3}$. Using point-slope form with $(6, -3)$: $y - (-3) = -\\frac{4}{3}(x - 6)$, which gives $y + 3 = -\\frac{4}{3}x + 8$, so $y = -\\frac{4}{3}x + 5$. The $y$-intercept is $5$. The value $-11$ results from using slope $\\frac{4}{3}$ instead of $-\\frac{4}{3}$, taking the reciprocal without negating; this gives $y + 3 = \\frac{4}{3}(x - 6) = \\frac{4}{3}x - 8$, so $y = \\frac{4}{3}x - 11$ with $y$-intercept $-11$. The value $-5$ results from a sign error, negating the correct $y$-intercept. The value $8$ results from expanding $-\\frac{4}{3}(x - 6)$ to get $-\\frac{4}{3}x + 8$ and reporting $8$ as the $y$-intercept without subtracting $3$ from both sides.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM297RGSW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The heights, in inches, of $7$ seedlings are listed below.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29J9BL3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A trapezoid has parallel bases of length $17$ centimeters and $23$ centimeters, and a height of $8$ centimeters. What is the area of the trapezoid, in square centimeters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '160', ARRAY['160'], E'The area of a trapezoid is $\\frac{1}{2}(b_1 + b_2) \\times h = \\frac{1}{2}(17 + 23)(8) = \\frac{1}{2}(40)(8) = 160$ square centimeters. A common error is forgetting the factor of $\\frac{1}{2}$ and computing $(17 + 23)(8) = 320$, which gives twice the correct area. Another error is multiplying only one base by the height, such as $23 \\times 8 = 184$, treating the trapezoid as a rectangle with only the longer base.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A9YOCL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has a radius of $18$ units. What is the area of the sector formed by a central angle of $80^\\circ$?', NULL, $lyceon_json$[{"key":"A","text":"$8\\pi$"},{"key":"B","text":"$72\\pi$"},{"key":"C","text":"$288\\pi$"},{"key":"D","text":"$324\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct sector area is $72\\pi$. The area of a sector is $\\frac{\\theta}{360} \\times \\pi r^2 = \\frac{80}{360} \\times \\pi(18)^2 = \\frac{2}{9} \\times 324\\pi = 72\\pi$. The value $8\\pi$ results from using the arc length formula instead of the sector area formula: $\\frac{80}{360} \\times 2\\pi(18) = \\frac{2}{9} \\times 36\\pi = 8\\pi$. The value $288\\pi$ comes from using the diameter ($36$) instead of the radius in $\\pi r^2$, computing $\\frac{2}{9} \\times \\pi(36)^2 = \\frac{2}{9} \\times 1296\\pi = 288\\pi$. The value $324\\pi$ results from computing the full circle area $\\pi(18)^2 = 324\\pi$ without applying the fractional portion for the central angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B131NJ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $9x - 37 = 71$?', NULL, $lyceon_json$[{"key":"A","text":"$-12$"},{"key":"B","text":"$\\frac{71}{9}$"},{"key":"C","text":"$12$"},{"key":"D","text":"$108$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding $37$ to both sides gives $9x = 108$, and dividing both sides by $9$ gives $x = 12$. The value $-12$ results from a sign error, negating the correct answer. The value $\\frac{71}{9}$ results from dividing $71$ by $9$ directly without first adding $37$, treating the equation as $9x = 71$. The value $108$ results from correctly computing $9x = 108$ but reporting $108$ as the answer without dividing by $9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BCZH0C', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 2x^2 - 20x + 53$. The function $g$ is defined by $g(x) = f(x + 6) - 9$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$-9$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'B', NULL, E'First, rewrite $f(x)$ in vertex form by completing the square: $f(x) = 2(x^2 - 10x) + 53 = 2(x^2 - 10x + 25 - 25) + 53 = 2(x - 5)^2 - 50 + 53 = 2(x - 5)^2 + 3$. The minimum value of $f$ is $3$, occurring at $x = 5$. Now, $g(x) = f(x + 6) - 9 = 2((x + 6) - 5)^2 + 3 - 9 = 2(x + 1)^2 - 6$. Since $(x + 1)^2 \\geq 0$, the minimum of $g$ is $-6$, occurring at $x = -1$. The distractor $3$ comes from finding the minimum of $f$ without applying the vertical shift of $-9$. The distractor $-9$ results from assuming the minimum of $f$ is $0$ and applying only the $-9$ shift. The distractor $12$ results from a sign error, computing $3 + 9 = 12$ instead of $3 - 9 = -6$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BGLU87', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A library had $156$ visitors on Saturday and $117$ visitors on Sunday. What is the percent decrease in the number of visitors from Saturday to Sunday?', NULL, $lyceon_json$[{"key":"A","text":"$25\\%$"},{"key":"B","text":"$33\\%$"},{"key":"C","text":"$39\\%$"},{"key":"D","text":"$75\\%$"}]$lyceon_json$::jsonb, 'A', NULL, E'The decrease is $156 - 117 = 39$ visitors. The percent decrease is $\\frac{39}{156} \\times 100 = 25\\%$. The value $33\\%$ results from dividing the decrease by Sunday''s total instead of Saturday''s: $\\frac{39}{117} \\approx 33.3\\%$. The value $39\\%$ confuses the absolute decrease of $39$ visitors with the percent decrease. The value $75\\%$ computes $\\frac{117}{156} = 75\\%$, which is the proportion of Saturday''s visitors that remained, not the percent decrease.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BX2LYY', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A workshop produces candles and soaps. Each candle requires $3$ hours of labor and $7$ ounces of wax. Each soap requires $5$ hours of labor and $4$ ounces of a base compound. The workshop has at most $53$ hours of labor and at most $61$ ounces of wax available per week. If the workshop produces $6$ candles in a week, what is the maximum number of whole soaps it can produce that same week?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$9$"},{"key":"C","text":"$12$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $s$ be the number of soaps. The labor constraint is $3(6) + 5s \\leq 53$, which simplifies to $18 + 5s \\leq 53$, giving $5s \\leq 35$, so $s \\leq 7$. The wax constraint applies only to candles: $7(6) = 42 \\leq 61$, which is satisfied and does not restrict soap production since soaps use a different material. The binding constraint is labor, giving a maximum of $7$ soaps. The value $9$ results from using the wax availability incorrectly for soaps: computing $(61 - 42) \\div 4 \\approx 4.75$ and adding that to $4$, reflecting partial reasoning with the wrong resource. The value $12$ comes from dividing $61$ by $5$ and rounding down, misapplying the total wax budget as if it were the labor budget. The value $4$ arises from swapping the labor coefficients for candles and soaps, setting up $5(6) + 3s \\leq 53$ and solving $30 + 3s \\leq 53$ to get $s \\leq 7.67$, then further miscalculating.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C15CR9', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'$$kx + 6y = 19$$ $$3x + 9y = 25$$ In the system of equations above, $k$ is a constant. If the system has no solution, what is the value of $k$ ?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$\\frac{3}{2}$"},{"key":"C","text":"$-2$"},{"key":"D","text":"$\\frac{2}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'A system of two linear equations has no solution when the lines are parallel: the ratios of the coefficients of $x$ and $y$ are equal, but the ratio of the constants is different. Setting $\\frac{k}{3} = \\frac{6}{9}$ gives $\\frac{k}{3} = \\frac{2}{3}$, so $k = 2$. Checking the constants: $\\frac{19}{25} \\neq \\frac{2}{3}$ (since $\\frac{2}{3} \\approx 0.667$ and $\\frac{19}{25} = 0.76$), confirming the system is inconsistent when $k = 2$. The value $\\frac{3}{2}$ results from incorrectly setting $\\frac{k}{3} = \\frac{9}{6}$ instead of $\\frac{6}{9}$, reversing the ratio of the $y$-coefficients. The value $-2$ introduces an erroneous negative sign when solving for $k$. The value $\\frac{2}{3}$ is the simplified ratio $\\frac{6}{9}$ itself rather than the result of multiplying both sides of $\\frac{k}{3} = \\frac{2}{3}$ by $3$ to obtain $k$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CAHXOX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $h$ is defined by $h(x) = (x - 7)^2 + 19$. What is the minimum value of $h(x)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19', ARRAY['19'], E'The function $h(x) = (x - 7)^2 + 19$ is in vertex form $a(x - h)^2 + k$ with $a = 1 > 0$, $h = 7$, and $k = 19$. Since the coefficient of the squared term is positive, the parabola opens upward and the vertex represents the minimum. The minimum value is $k = 19$, occurring at $x = 7$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CJV7HM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The graphs of $y = x^2 - 6x + 2$ and $y = 3x - 16$ intersect at two points. What is the sum of the $y$-coordinates of the two points of intersection?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$2$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'B', NULL, E'Set the two expressions equal: $x^2 - 6x + 2 = 3x - 16$, which simplifies to $x^2 - 9x + 18 = 0$. Factoring gives $(x - 3)(x - 6) = 0$, so $x = 3$ or $x = 6$. Substituting into $y = 3x - 16$: when $x = 3$, $y = 9 - 16 = -7$; when $x = 6$, $y = 18 - 16 = 2$. The sum of the $y$-coordinates is $-7 + 2 = -5$. The distractor $9$ comes from computing the sum of the $x$-coordinates ($3 + 6 = 9$) instead of the $y$-coordinates. The distractor $2$ results from finding only one intersection point and reporting its $y$-value. The distractor $5$ results from a sign error, computing $7 - 2 = 5$ instead of $-7 + 2 = -5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CSF3F1', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $5(3x^2 + 7x - 2) - 3(4x^2 - x + 9)$?', NULL, $lyceon_json$[{"key":"A","text":"$3x^2 + 38x - 37$"},{"key":"B","text":"$27x^2 + 38x - 37$"},{"key":"C","text":"$3x^2 + 32x - 37$"},{"key":"D","text":"$3x^2 + 38x + 17$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing the first term gives $15x^2 + 35x - 10$. Distributing the second term gives $-12x^2 + 3x - 27$. Combining like terms: $(15 - 12)x^2 = 3x^2$, $(35 + 3)x = 38x$, and $-10 - 27 = -37$. The result is $3x^2 + 38x - 37$. The distractor $27x^2 + 38x - 37$ comes from adding the $x^2$ coefficients as $15 + 12 = 27$ instead of subtracting. The distractor $3x^2 + 32x - 37$ results from a sign error when distributing $-3$ to $-x$, yielding $-3x$ instead of $+3x$, so $35 - 3 = 32$. The distractor $3x^2 + 38x + 17$ results from an arithmetic slip on the constants, computing $-10 + 27 = 17$ instead of $-10 - 27 = -37$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DD3ZFG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $13$ red marbles, $9$ yellow marbles, and $5$ white marbles. If one marble is selected at random, what is the probability that it is yellow?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{22}$"},{"key":"B","text":"$\\frac{9}{27}$"},{"key":"C","text":"$\\frac{9}{13}$"},{"key":"D","text":"$\\frac{1}{9}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of marbles is $13 + 9 + 5 = 27$. The probability of selecting a yellow marble is $\\frac{9}{27}$, which simplifies to $\\frac{1}{3}$. The value $\\frac{9}{22}$ results from miscounting the total as $22$ by omitting the white marbles. The value $\\frac{9}{13}$ uses only the red marble count as the denominator instead of the full total. The value $\\frac{1}{9}$ confuses the count of yellow marbles with the total number of marbles, treating each yellow marble as equally likely to be any of $9$ outcomes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DWGHRR', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'$$5x + 2y = 23$$ $$5x - 2y = 7$$ What is the value of $y$ in the solution to the system of equations above?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Subtracting the second equation from the first eliminates $x$: $(5x + 2y) - (5x - 2y) = 23 - 7$, which gives $4y = 16$, so $y = 4$. This can be verified by adding the equations: $10x = 30$, so $x = 3$, and checking $5(3) + 2(4) = 15 + 8 = 23$ and $5(3) - 2(4) = 15 - 8 = 7$, both of which are correct.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FJK3J3', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'grid_in', E'In the equation $7x + 3y = 59$, if $x = 5$, what is the value of $y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Substituting $x = 5$ gives $7(5) + 3y = 59$, which simplifies to $35 + 3y = 59$. Subtracting $35$ from both sides yields $3y = 24$, and dividing by $3$ gives $y = 8$. A common error is a sign mistake when isolating $y$, such as computing $59 + 35 = 94$ and obtaining $y = \\frac{94}{3}$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FRCSOT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What are the solutions to the equation $\\sqrt{6x + 19} = x + 2$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$ only"},{"key":"B","text":"$5$ only"},{"key":"C","text":"$-3$ and $5$"},{"key":"D","text":"$-5$ only"}]$lyceon_json$::jsonb, 'B', NULL, E'Squaring both sides gives $6x + 19 = (x + 2)^2 = x^2 + 4x + 4$. Rearranging: $x^2 - 2x - 15 = 0$, which factors as $(x - 5)(x + 3) = 0$, yielding $x = 5$ or $x = -3$. Both must be checked in the original equation. For $x = -3$: $\\sqrt{6(-3) + 19} = \\sqrt{1} = 1$ but $-3 + 2 = -1$, so $1 \\neq -1$ and $x = -3$ is extraneous. For $x = 5$: $\\sqrt{6(5) + 19} = \\sqrt{49} = 7$ and $5 + 2 = 7$, which checks. The only valid solution is $5$. The distractor stating $-3$ only is the extraneous root that fails because the right side is negative while the square root is positive. The distractor stating both $-3$ and $5$ results from solving the quadratic correctly but failing to check for extraneous solutions introduced by squaring. The distractor $-5$ results from a sign error when solving $x - 5 = 0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G5BOEC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers want to determine whether a new ergonomic keyboard reduces wrist strain. They recruit $180$ office workers from three departments at the same technology company ($60$ per department). In each department, $30$ workers are randomly assigned to use the new keyboard and $30$ continue with their current keyboard. After $14$ weeks, wrist strain scores are compared. A reviewer notes that all three departments are in the same building, and the workers are all software engineers with similar daily typing habits. Which of the following is the most significant limitation of this study?', NULL, $lyceon_json$[{"key":"A","text":"The study does not use random assignment, so causation cannot be established."},{"key":"B","text":"A sample of $180$ office workers is too small to detect any meaningful difference in wrist strain."},{"key":"C","text":"Because the departments share the same building and job type, the results may not generalize to workers in different occupations or work environments."},{"key":"D","text":"Fourteen weeks is not enough time for any keyboard to affect wrist strain."}]$lyceon_json$::jsonb, 'C', NULL, E'The study does use random assignment within each department, so it can establish a causal relationship for the population it represents. However, all three departments are in the same building with workers who are all software engineers with similar typing habits, so the results may not generalize to workers in different occupations or work environments. The claim that the study lacks random assignment is factually incorrect — workers were randomly assigned to treatment groups within each department. The claim that $180$ workers is too small is not the most significant limitation; this sample size is reasonable for detecting moderate effects in a controlled experiment. The claim that fourteen weeks is too short makes an unsupported assumption and is not the limitation identified by the reviewer''s observation about the homogeneity of the sample.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G65LMT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In a triangle, two of the interior angles measure $62^\\circ$ and $83^\\circ$. What is the measure, in degrees, of the third interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$25^\\circ$"},{"key":"B","text":"$35^\\circ$"},{"key":"C","text":"$45^\\circ$"},{"key":"D","text":"$145^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of interior angles in any triangle is $180^\\circ$. The third angle is $180 - 62 - 83 = 35$, so the correct measure is $35^\\circ$. The value $25^\\circ$ results from an arithmetic slip, such as computing $62 + 83 = 155$ instead of $145$ and then subtracting from $180$. The value $45^\\circ$ arises from a different arithmetic slip in the subtraction step, for example miscalculating $180 - 145$ as $45$ instead of $35$. The value $145^\\circ$ results from misreading the question and reporting the sum of the two given angles rather than the missing third angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GZCVWV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'grid_in', E'The line of best fit for a data set is given by $y = 4.3x + 11.7$. What is the predicted value of $y$ when $x = 9$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '50.4', ARRAY['252/5', '50.4'], E'Substituting $x = 9$ into the equation gives $y = 4.3(9) + 11.7 = 38.7 + 11.7 = 50.4$. A common error is to forget the $y$-intercept, giving $38.7$ alone. Another error is to add $4.3 + 9 + 11.7 = 25$ instead of multiplying the slope by $x$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H60DF5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $175$ employees at a large firm found that $38\\%$ are satisfied with their current work schedule, with a margin of error of $7$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $38\\%$ of all employees at the firm are satisfied with their current work schedule."},{"key":"B","text":"Between $31\\%$ and $45\\%$ of the sampled employees are satisfied with their current work schedule."},{"key":"C","text":"It is plausible that between $31\\%$ and $45\\%$ of all employees at the firm are satisfied with their current work schedule."},{"key":"D","text":"If the survey is repeated, exactly $38\\%$ of the new sample will be satisfied with their current work schedule."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error of $7$ percentage points means the plausible range for the population proportion is $38\\% \\pm 7\\%$, or between $31\\%$ and $45\\%$. This interval applies to all employees at the firm, not just those sampled. The claim that exactly $38\\%$ of all employees are satisfied treats the sample statistic as the exact population value, ignoring sampling variability. The claim that the interval describes the sampled employees confuses the sample, which was directly observed at $38\\%$, with the population inference. The claim that a new sample would yield exactly $38\\%$ misunderstands that different random samples produce different results.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I2L2CU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A meteorologist records the average daily temperature in degrees Fahrenheit, $x$, and the number of hot beverages sold at a campus cafe, $y$. The equation of the line of best fit is $y = -3.4x + 289$. Which of the following is the best interpretation of the number $-3.4$ in this equation?', NULL, $lyceon_json$[{"key":"A","text":"For each one-degree increase in temperature, the predicted number of hot beverages sold decreases by $3.4$."},{"key":"B","text":"For each one-degree increase in temperature, the predicted number of hot beverages sold increases by $3.4$."},{"key":"C","text":"When the temperature is $0$ degrees Fahrenheit, the predicted number of hot beverages sold is $3.4$."},{"key":"D","text":"When $3.4$ hot beverages are sold, the predicted temperature is $0$ degrees Fahrenheit."}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation $y = -3.4x + 289$, the coefficient $-3.4$ is the slope, which represents the predicted change in $y$ for each unit increase in $x$. In context, for each one-degree increase in average daily temperature, the predicted number of hot beverages sold decreases by $3.4$. The interpretation that sales increase by $3.4$ per degree ignores the negative sign of the slope. The interpretation that $3.4$ represents the predicted sales at $0$ degrees confuses the slope with the $y$-intercept, which is $289$. The interpretation involving $3.4$ beverages and $0$ degrees reverses the roles of the independent and dependent variables and misidentifies the meaning of the slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J5SAOZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A $26$-foot ladder leans against a vertical wall with the base of the ladder $10$ feet from the wall on level ground. How many feet up the wall does the ladder reach?', NULL, $lyceon_json$[{"key":"A","text":"$16$"},{"key":"B","text":"$24$"},{"key":"C","text":"$36$"},{"key":"D","text":"$\\sqrt{776}$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Pythagorean theorem, the height up the wall is $\\sqrt{26^2 - 10^2} = \\sqrt{676 - 100} = \\sqrt{576} = 24$ feet. The value $16$ results from subtracting the lengths directly ($26 - 10 = 16$) instead of using the Pythagorean theorem. The value $36$ comes from adding the lengths ($26 + 10 = 36$), misreading the question as asking for a sum rather than applying the theorem. The value $\\sqrt{776}$ results from adding $26^2 + 10^2 = 676 + 100 = 776$ instead of subtracting, setting up the equation as though the known values were both legs rather than the hypotenuse and one leg.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JS6MW1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A data set of $7$ values has a mean of $46$. When three new values, $31$, $55$, and $62$, are added to the data set, what is the mean of the resulting $10$ values?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '47', ARRAY['47'], E'The sum of the original $7$ values is $7 \\times 46 = 322$. Adding $31$, $55$, and $62$ gives a new sum of $322 + 31 + 55 + 62 = 470$. The mean of the $10$ values is $\\frac{470}{10} = 47$. A common error is to average the three new values with the old mean: $\\frac{46 + 31 + 55 + 62}{4} = 48.5$, which does not properly weight by the number of values. Another error is to divide by $7$ instead of $10$ after adding the new values, giving $\\frac{470}{7} \\approx 67.1$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KBLYF7', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{4x^3 + 28x}{2x^2 + 14}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$2x$"},{"key":"B","text":"$2x + 2$"},{"key":"C","text":"$2x^2 + 14x$"},{"key":"D","text":"$\\frac{2x + 14}{x}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the numerator: $4x^3 + 28x = 4x(x^2 + 7)$. Factor the denominator: $2x^2 + 14 = 2(x^2 + 7)$. Cancel the common factor $(x^2 + 7)$: $\\frac{4x(x^2 + 7)}{2(x^2 + 7)} = \\frac{4x}{2} = 2x$. The distractor $2x + 2$ comes from an arithmetic slip, incorrectly simplifying $\\frac{4x}{2}$ as $2x + 2$ by mishandling the division. The distractor $2x^2 + 14x$ results from cancelling only the constant $2$ from numerator and denominator without also cancelling the common factor $(x^2 + 7)$. The distractor $\\frac{2x + 14}{x}$ results from incorrectly splitting the fraction term by term rather than factoring.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KFXSTF', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 31x - 59$. What is the value of $f(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$-65$"},{"key":"B","text":"$-24$"},{"key":"C","text":"$65$"},{"key":"D","text":"$183$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 4$ gives $f(4) = 31(4) - 59 = 124 - 59 = 65$. The value $-65$ results from a sign error, negating the correct answer. The value $-24$ results from an arithmetic slip of adding $31 + 4 = 35$ instead of multiplying $31 \\times 4 = 124$, then computing $35 - 59 = -24$. The value $183$ comes from adding $59$ instead of subtracting it, giving $124 + 59 = 183$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KX4FUB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A printing press produces $17$ identical posters every $6$ minutes. At this constant rate, how many posters does the press produce in $42$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$102$"},{"key":"B","text":"$119$"},{"key":"C","text":"$204$"},{"key":"D","text":"$714$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{17 \\text{ posters}}{6 \\text{ minutes}}$. In $42$ minutes, the number of posters produced is $\\frac{17}{6} \\times 42 = \\frac{714}{6} = 119$. The value $102$ results from an arithmetic slip such as computing $17 \\times 6 = 102$, confusing the rate denominator with a multiplier. The value $204$ comes from computing $\\frac{17 \\times 42}{6}$ incorrectly as $17 \\times 12 = 204$. The value $714$ results from computing $17 \\times 42 = 714$ without dividing by $6$, ignoring that $17$ posters are produced per $6$ minutes, not per $1$ minute.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M6OTGI', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A water tank initially contains 2,470 liters. Water drains from the tank at a constant rate of 53 liters per hour. Which function $w(t)$ gives the volume of water, in liters, remaining in the tank $t$ hours after draining begins?', NULL, $lyceon_json$[{"key":"A","text":"$w(t) = 2470 + 53t$"},{"key":"B","text":"$w(t) = 53t - 2470$"},{"key":"C","text":"$w(t) = 2470 - 53t$"},{"key":"D","text":"$w(t) = 2470 - \\frac{t}{53}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The tank starts with 2,470 liters and loses 53 liters each hour, so the volume remaining after $t$ hours is $w(t) = 2470 - 53t$. The expression $2470 + 53t$ incorrectly adds water over time instead of subtracting, a sign error that ignores the draining. The expression $53t - 2470$ reverses the roles of the initial volume and the rate term, producing negative values almost immediately. The expression $2470 - \\frac{t}{53}$ uses the reciprocal of the rate, confusing 53 liters per hour with 1 liter every 53 hours.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MGRS8V', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one acute angle measures $37^\\circ$ and the side adjacent to this angle has length $40$. What is the length of the hypotenuse, to the nearest tenth? (Use $\\sin 37^\\circ \\approx 0.6018$ and $\\cos 37^\\circ \\approx 0.7986$.)', NULL, $lyceon_json$[{"key":"A","text":"$24.1$"},{"key":"B","text":"$31.9$"},{"key":"C","text":"$50.1$"},{"key":"D","text":"$66.5$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct length is $50.1$. Using the cosine ratio, $\\cos 37^\\circ = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{40}{\\text{hypotenuse}}$, so $\\text{hypotenuse} = \\frac{40}{\\cos 37^\\circ} = \\frac{40}{0.7986} \\approx 50.1$. The value $24.1$ results from computing $40 \\times \\sin 37^\\circ = 40 \\times 0.6018 \\approx 24.1$, which gives the opposite side rather than the hypotenuse. The value $31.9$ results from multiplying $40 \\times \\cos 37^\\circ = 40 \\times 0.7986 \\approx 31.9$ instead of dividing, setting up the equation incorrectly. The value $66.5$ comes from dividing by sine ($\\frac{40}{0.6018} \\approx 66.5$), misreading the adjacent side as the opposite side.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O0XZ4J', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the slope of the line that passes through the points $(-3, 14)$ and $(9, -22)$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$-\\frac{1}{3}$"},{"key":"C","text":"$\\frac{1}{3}$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope formula gives $m = \\frac{-22 - 14}{9 - (-3)} = \\frac{-36}{12} = -3$. The value $-\\frac{1}{3}$ results from inverting the fraction, computing the change in $x$ over the change in $y$ instead of rise over run. The value $\\frac{1}{3}$ compounds the inversion error with a sign error, losing the negative. The value $3$ results from dropping the negative sign from the correct calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ODTP5I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A dentist wants to determine whether using an electric toothbrush causes a reduction in cavities. The dentist asks $65$ patients to switch to an electric toothbrush for $9$ months and then counts their new cavities. No control group is included. Which of the following is a valid conclusion from this study?', NULL, $lyceon_json$[{"key":"A","text":"Any observed reduction in cavities was caused by using an electric toothbrush."},{"key":"B","text":"The study shows that electric toothbrushes have no effect on cavity rates."},{"key":"C","text":"The study cannot establish that using an electric toothbrush caused any observed change in cavity rates."},{"key":"D","text":"Because the patients were the dentist's own patients, the results apply to all dental patients."}]$lyceon_json$::jsonb, 'C', NULL, E'Without a control group, any observed change in cavities cannot be attributed to the electric toothbrush, because other factors such as changes in diet, improved hygiene habits, or the placebo effect could account for the results. The claim that any reduction was caused by the electric toothbrush incorrectly infers causation without a control group to isolate the effect. The claim that electric toothbrushes have no effect goes beyond what the study can determine — the absence of a control group means no causal conclusion can be drawn in either direction. The claim that results apply to all dental patients overgeneralizes from a convenience sample of one dentist''s patients, which is not randomly selected from any broader population.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OH6HDP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are drawn from the same large population of licensed drivers. Sample J consists of $150$ drivers and finds that $61\\%$ regularly use a navigation app, with a margin of error of $\\pm 8.1$ percentage points. Sample K consists of $600$ drivers and finds that $54\\%$ regularly use a navigation app, with a margin of error of $\\pm 4.0$ percentage points. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The true population proportion is $54\\%$ because Sample K is four times as large as Sample J."},{"key":"B","text":"The results contradict each other, so at least one sample must have been collected incorrectly."},{"key":"C","text":"Since both samples are from the same population, the true proportion must be the weighted average of $61\\%$ and $54\\%$."},{"key":"D","text":"The confidence intervals from both samples overlap, so the results are consistent with each other."}]$lyceon_json$::jsonb, 'D', NULL, E'Sample J''s confidence interval is $52.9\\%$ to $69.1\\%$, and Sample K''s confidence interval is $50.0\\%$ to $58.0\\%$. These intervals overlap in the range from about $52.9\\%$ to $58.0\\%$, so both results are consistent with each other and could reflect the same population proportion. The claim that the true proportion is $54\\%$ because Sample K is larger confuses a larger sample with certainty about the point estimate — a larger sample provides greater precision but does not guarantee the point estimate equals the parameter. The claim that the results contradict each other misunderstands that different random samples naturally produce different point estimates; the overlapping intervals show no contradiction. The claim that the true proportion must equal a weighted average of the two estimates has no statistical basis — the population proportion is a fixed value not determined by averaging sample results.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OITUMF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $280$ apartments in a city with $6{,}300$ rental apartments and finds that $34\\%$ of the sample have in-unit laundry. The margin of error for the survey is $\\pm 5.7$ percentage points. Based on this information, which of the following is a plausible estimate for the number of rental apartments in the entire city that have in-unit laundry?', NULL, $lyceon_json$[{"key":"A","text":"$1{,}512$"},{"key":"B","text":"$2{,}142$"},{"key":"C","text":"$2{,}583$"},{"key":"D","text":"$1{,}134$"}]$lyceon_json$::jsonb, 'B', NULL, E'The plausible range for the population proportion is $34\\% \\pm 5.7\\%$, which is $28.3\\%$ to $39.7\\%$. Applying this to $6{,}300$ apartments gives a range of $0.283 \\times 6{,}300 = 1{,}782.9$ to $0.397 \\times 6{,}300 = 2{,}501.1$. The value $2{,}142$ equals $0.34 \\times 6{,}300$ and falls within this interval, making it plausible. The value $1{,}512$ equals $0.24 \\times 6{,}300$, which is below the lower bound and outside the confidence interval. The value $2{,}583$ equals approximately $0.41 \\times 6{,}300$, which exceeds the upper bound of $39.7\\%$. The value $1{,}134$ equals $0.18 \\times 6{,}300$, which is far below the plausible range and likely results from a calculation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OSAYJP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = 5^{x-3} + 11$. Which of the following describes the range of $f$?', NULL, $lyceon_json$[{"key":"A","text":"All real numbers greater than $11$"},{"key":"B","text":"All real numbers greater than or equal to $11$"},{"key":"C","text":"All real numbers greater than $3$"},{"key":"D","text":"All real numbers"}]$lyceon_json$::jsonb, 'A', NULL, E'The base exponential $5^{x-3}$ is always positive for all real $x$, approaching $0$ as $x \\to -\\infty$ but never equaling $0$. Adding $11$ shifts the output up by $11$, so $f(x) > 11$ for all $x$, but $f(x)$ never equals $11$. Therefore the range is all real numbers greater than $11$. The choice stating greater than or equal to $11$ incorrectly includes $11$, which would require $5^{x-3} = 0$, an impossibility for exponential functions. The choice stating greater than $3$ confuses the horizontal shift parameter with the vertical asymptote. The choice stating all real numbers ignores that exponential functions with a positive base always produce positive outputs, making values at or below $11$ unreachable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OZ8QNL', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function $f$ is defined by $f(x) = 19x - 47$. A new function $g$ is defined by $g(x) = f(3x + 5)$. What is the $y$-intercept of the graph of $y = g(x)$ in the $xy$-plane?', NULL, $lyceon_json$[{"key":"A","text":"$-47$"},{"key":"B","text":"$5$"},{"key":"C","text":"$48$"},{"key":"D","text":"$95$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substitute $3x + 5$ into $f$: $g(x) = f(3x + 5) = 19(3x + 5) - 47 = 57x + 95 - 47 = 57x + 48$. The $y$-intercept occurs at $x = 0$, giving $g(0) = 48$. The value $-47$ comes from using the $y$-intercept of $f$ without performing the composition. The value $5$ confuses the constant in the input expression $3x + 5$ with the output intercept. The value $95$ results from computing $19 \\cdot 5 = 95$ but failing to subtract $47$, completing only part of the composition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P73BTY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A pipeline pumps $83$ gallons of water every $5$ minutes. A storage tank holds $1{,}992$ gallons. At this constant rate, how many minutes does it take to fill the tank completely?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '120', ARRAY['120'], E'The pump rate is $\\frac{83}{5} = 16.6$ gallons per minute. To fill $1{,}992$ gallons, the time required is $\\frac{1{,}992}{16.6} = 120$ minutes. Equivalently, $\\frac{1{,}992}{83} = 24$ intervals of $5$ minutes each, so $24 \\times 5 = 120$ minutes. A common error is to divide $1{,}992$ by $83$ alone and stop at $24$, forgetting to multiply by $5$ to convert intervals to minutes. Another error is to divide $1{,}992$ by $5$ instead of by the rate, yielding $398.4$ minutes.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PEGXY4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store''s monthly profit was $170{,}000$ dollars in January. Profit increased by $15\\%$ in February and then decreased by $24\\%$ in March. What was the profit, in dollars, in March?', NULL, $lyceon_json$[{"key":"A","text":"$148{,}580$"},{"key":"B","text":"$154{,}700$"},{"key":"C","text":"$170{,}000$"},{"key":"D","text":"$195{,}500$"}]$lyceon_json$::jsonb, 'A', NULL, E'February profit is $170{,}000 \\times 1.15 = 195{,}500$ dollars. March profit after a $24\\%$ decrease is $195{,}500 \\times 0.76 = 148{,}580$ dollars. The value $154{,}700$ results from applying only the net percentage change of $15\\% - 24\\% = -9\\%$ to the original: $170{,}000 \\times 0.91 = 154{,}700$, which incorrectly assumes percentage changes are additive. The value $170{,}000$ assumes the increase and decrease cancel out, leaving profit unchanged. The value $195{,}500$ is the February profit, reflecting a failure to apply the March decrease.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QYBG2Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher models the relationship between hours of weekly exercise, $x$, and resting heart rate in beats per minute, $y$, with the equation $y = -1.7x + 83$. At $x = 11$ hours, the observed resting heart rate is $62.3$ beats per minute. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$2$"},{"key":"C","text":"$-64.3$"},{"key":"D","text":"$64.3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted resting heart rate at $x = 11$ is $y = -1.7(11) + 83 = -18.7 + 83 = 64.3$ beats per minute. The residual is defined as observed minus predicted: $62.3 - 64.3 = -2$. A negative residual indicates the model overpredicted the resting heart rate at this exercise level. The value $2$ results from computing predicted minus observed ($64.3 - 62.3$), reversing the residual formula and getting the wrong sign. The value $-64.3$ arises from subtracting the predicted value from zero instead of from the observed value. The value $64.3$ is the predicted value itself, not the residual, reflecting a failure to compute the difference between observed and predicted values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RIMQGH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A town''s population increased by $14\\%$ from $2018$ to $2022$. If the population in $2022$ was $39{,}330$, what was the population in $2018$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '34500', ARRAY['34500'], E'Let the population in $2018$ be $p$. After a $14\\%$ increase, the population is $1.14p$. Setting $1.14p = 39{,}330$ gives $p = \\frac{39{,}330}{1.14} = 34{,}500$. A common error is to subtract $14\\%$ of $39{,}330$ from $39{,}330$: $39{,}330 \\times 0.14 = 5{,}506.2$, giving $39{,}330 - 5{,}506.2 = 33{,}823.8$, which incorrectly applies the percentage to the final value rather than the original. Another error is to divide by $0.14$ instead of $1.14$, yielding an unreasonably large number.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RZ6TBO', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ in the equation $$\\frac{3(5x + 7)}{11} = 9\\;?$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '26/5', ARRAY['26/5', '5.2'], E'Multiply both sides by $11$ to get $3(5x + 7) = 99$. Divide both sides by $3$ to get $5x + 7 = 33$. Subtract $7$ from both sides: $5x = 26$. Divide by $5$: $x = \\frac{26}{5}$. A common error is forgetting to distribute the $3$, solving $5x + 7 = 99$ to get $5x = 92$ and $x = \\frac{92}{5}$. Another error is multiplying by $11$ on only one side of the equation.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SFJ3H2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $x^2 + 5x - 84 = 0$ and $x > 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Factor the quadratic: $x^2 + 5x - 84 = (x + 12)(x - 7) = 0$. Setting each factor to zero gives $x = -12$ or $x = 7$. Since the problem requires $x > 0$, the answer is $7$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ST4M5J', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A craft workshop charges $13$ dollars per participant plus a one-time room rental fee of $47$ dollars. If the organizer can spend no more than $177$ dollars total, what is the greatest number of participants the workshop can accommodate?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'Let $p$ represent the number of participants. The total cost is $13p + 47$, and this must satisfy $13p + 47 \\leq 177$. Subtracting $47$ from both sides gives $13p \\leq 130$. Dividing both sides by $13$ gives $p \\leq 10$. Since $p$ must be a whole number, the greatest number of participants is $10$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TVT759', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $9x + 17 \\leq 80$ ?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$7$"},{"key":"C","text":"$11$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtracting $17$ from both sides of $9x + 17 \\leq 80$ gives $9x \\leq 63$. Dividing both sides by $9$ yields $x \\leq 7$. Among the choices, only $7$ satisfies this inequality. The value $8$ is close but exceeds the bound, since $9(8) + 17 = 89 > 80$. The value $11$ reflects ignoring the coefficient of $x$ and treating the problem as $x + 17 \\leq 80$, giving $x \\leq 63$, then selecting a value well above the true bound. The value $10$ comes from computing $80 - 17 = 63$ but then rounding $63 \\div 9$ upward instead of recognizing that $7$ is the largest integer satisfying the inequality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UWTYK1', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'$$3x + 2y = 23$$ $$5x - 2y = 17$$ What is the value of $2x + y$ for the solution $(x, y)$ to the system of equations above?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$14$"},{"key":"C","text":"$17$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations eliminates $y$: $(3x + 2y) + (5x - 2y) = 23 + 17$, which gives $8x = 40$, so $x = 5$. Substituting into the first equation: $3(5) + 2y = 23$ gives $2y = 8$, so $y = 4$. Therefore $2x + y = 2(5) + 4 = 14$. The value $9$ results from computing $x + y = 5 + 4$ instead of the requested $2x + y$, solving correctly but evaluating the wrong expression. The value $17$ comes from confusing the right-hand side of the second equation with the requested quantity. The value $6$ arises from a sign error when computing $2(5) - 4 = 6$, subtracting $y$ instead of adding it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W1HZWH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of $13$ values has a mean of $74$ and a median of $71$. The smallest value in the data set, which is $38$, is replaced by $8$. Which of the following correctly describes the effect on the mean and median?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases by $\\frac{30}{13}$ and the median stays the same."},{"key":"B","text":"Both the mean and median decrease by $\\frac{30}{13}$."},{"key":"C","text":"The mean decreases by $30$ and the median stays the same."},{"key":"D","text":"Both the mean and median stay the same."}]$lyceon_json$::jsonb, 'A', NULL, E'Replacing $38$ with $8$ decreases the sum by $38 - 8 = 30$. The original sum is $13 \\times 74 = 962$, and the new sum is $932$. The new mean is $\\frac{932}{13} = 74 - \\frac{30}{13} \\approx 71.69$, a decrease of $\\frac{30}{13}$. The median is the $7$th value in the ordered list. Since $38$ was the smallest value and was replaced by an even smaller value ($8$), the $7$th value in the ordered list is unchanged, so the median remains $71$. The claim that both the mean and median decrease by $\\frac{30}{13}$ incorrectly assumes that changing the smallest value affects the middle of the distribution. The claim that the mean decreases by $30$ confuses the change in the sum with the change in the mean, forgetting to divide by $13$. The claim that both stay the same fails to account for the effect on the sum and therefore the mean.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WHE1UG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A bookstore surveyed $310$ customers about their preferred format (print or digital) and whether they have a loyalty card (yes or no). Of the $310$ customers, $127$ have a loyalty card and $183$ do not. Among those with a loyalty card, $79$ prefer digital format. Among those without a loyalty card, $58$ prefer digital format. If a customer is selected at random from those who prefer print format, what is the probability that the customer has a loyalty card?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{48}{173}$"},{"key":"B","text":"$\\frac{48}{310}$"},{"key":"C","text":"$\\frac{48}{127}$"},{"key":"D","text":"$\\frac{125}{173}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Loyalty-card holders who prefer print number $127 - 79 = 48$. Non-loyalty-card holders who prefer print number $183 - 58 = 125$. The total number of print-preferring customers is $48 + 125 = 173$. The conditional probability that a print-preferring customer has a loyalty card is $\\frac{48}{173}$. The value $\\frac{48}{310}$ incorrectly uses the total number of customers as the denominator instead of conditioning on print preference. The value $\\frac{48}{127}$ divides by the total number of loyalty-card holders rather than the total number of print-preferring customers. The value $\\frac{125}{173}$ gives the probability that a print-preferring customer does not have a loyalty card, which answers the reverse of the question.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WKXFNL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A surveyor stands at point $A$ and measures the angle of elevation to the top of a building at point $C$ as $\\theta$, where $\\tan \\theta = \\frac{3}{4}$. She walks $26$ meters directly toward the building to point $B$, where the angle of elevation to $C$ is $\\phi$, with $\\tan \\phi = \\frac{3}{2}$. What is the height of the building, in meters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '39', ARRAY['39'], E'Let $h$ be the height of the building and $d$ be the horizontal distance from point $B$ to the base of the building. From point $B$, $\\tan \\phi = \\frac{h}{d} = \\frac{3}{2}$, so $h = \\frac{3d}{2}$. From point $A$, the horizontal distance to the base is $d + 26$, and $\\tan \\theta = \\frac{h}{d + 26} = \\frac{3}{4}$, so $h = \\frac{3(d + 26)}{4}$. Setting the two expressions for $h$ equal: $\\frac{3d}{2} = \\frac{3(d + 26)}{4}$. Multiplying both sides by $4$ gives $6d = 3d + 78$, so $3d = 78$ and $d = 26$. Therefore $h = \\frac{3(26)}{2} = 39$. A common error is setting up the tangent ratios with the wrong sides, for example using $\\tan \\theta = \\frac{d + 26}{h}$ instead of $\\frac{h}{d + 26}$. Another error is forgetting that the distance from $A$ to the base is $d + 26$, not $d$, leading to an incorrect system of equations.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y5U86U', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has an area of $256\\pi$ square centimeters. What is the circumference of the circle, in centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$16\\pi$"},{"key":"B","text":"$32\\pi$"},{"key":"C","text":"$256\\pi$"},{"key":"D","text":"$512\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct circumference is $32\\pi$ centimeters. Using the area formula $A = \\pi r^2$, setting $\\pi r^2 = 256\\pi$ gives $r^2 = 256$, so $r = 16$. The circumference is $C = 2\\pi r = 2\\pi(16) = 32\\pi$. The value $16\\pi$ results from computing $\\pi r$ instead of $2\\pi r$, omitting the factor of $2$ in the circumference formula. The value $256\\pi$ results from restating the area rather than computing the circumference, misreading what the question asks. The value $512\\pi$ comes from computing $2\\pi r^2 = 2\\pi(256) = 512\\pi$, incorrectly mixing the area and circumference formulas.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20YIGI4', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Literary scholar Anjali Mukherjee contends that the narrator of Bankimchandra Chattopadhyay''s 1882 novel Anandamath does not merely describe the famine ravaging Bengal but rather ______ it, rendering starvation in such aestheticized prose that readers may register the beauty of the language before confronting the horror of the events depicted.', $lyceon_json$[{"key":"A","text":"transfigures"},{"key":"B","text":"adjudicates"},{"key":"C","text":"subsidizes"},{"key":"D","text":"inventories"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts mere description with a process of rendering starvation in aestheticized prose so that beauty registers before horror. The word meaning to transform something into something more beautiful or elevated captures this artistic transformation of suffering into aestheticized language. The word meaning to make a formal judgment or decision in a dispute describes a legal or evaluative process unrelated to the literary transformation the passage describes. The word meaning to support financially by paying part of the cost describes economic assistance, which has no connection to the narrator''s aesthetic treatment of famine. The word meaning to make a detailed list or catalog describes systematic enumeration, which is closer to the mere description the passage contrasts with the narrator''s actual method.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22HBJ0U', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologist Lena Vukovic has proposed that the distinctive herringbone brickwork found in several 14th-century churches along the Dalmatian coast was introduced by itinerant masons from Lombardy, citing stylistic parallels with churches near Pavia. ______ Vukovic acknowledges that recent petrographic analysis of the bricks themselves reveals they were manufactured from local Adriatic clay, not imported, a finding that complicates but does not, in her view, refute the Lombard-origin hypothesis, since the masons could have applied a familiar technique to locally sourced materials.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"To be sure,"},{"key":"C","text":"As a result,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'B', NULL, E'The second sentence presents evidence (local clay origin) that appears to challenge Vukovic''s hypothesis before she explains why it does not ultimately undermine her argument. The transition "To be sure" correctly signals a concessive move in which the speaker acknowledges a complicating piece of evidence before maintaining her original position. The option "Moreover" implies the second sentence adds supporting evidence, but the petrographic finding is a complication, not additional support. The option "As a result" implies a causal consequence, suggesting the local-clay finding was caused by the Lombard-origin hypothesis, which is illogical. The option "In other words" signals a restatement, but the second sentence introduces new empirical evidence rather than rephrasing the hypothesis stated in the first sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22W82D4', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Marine biologist Keiko Fujimura recently completed a three-year survey of sea cucumber populations along the Sanriku coast of northeastern Japan. Fujimura found that sea cucumbers in rocky intertidal pools exposed to strong wave action grew 29 percent more slowly than those in sheltered coves, but the wave-exposed individuals had body walls nearly twice as thick. Fujimura attributes this difference to the mechanical stress of constant wave impact, which stimulates collagen deposition in the body wall at the expense of overall growth. The thicker body walls appear to reduce injury rates: wave-exposed sea cucumbers showed 78 percent fewer tissue lacerations than their sheltered counterparts during typhoon season.', $lyceon_json$[{"key":"A","text":"Sea cucumbers exposed to strong waves grow more slowly but develop thicker, more injury-resistant body walls than those in calmer waters."},{"key":"B","text":"The Sanriku coast is uniquely suited to sea cucumber aquaculture because of its varied wave conditions."},{"key":"C","text":"Sea cucumbers in sheltered coves face greater predation pressure than those in wave-exposed pools."},{"key":"D","text":"Collagen deposition in marine invertebrates is primarily determined by water temperature rather than mechanical stress."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Fujimura''s finding that wave-exposed sea cucumbers trade growth speed for thicker body walls through collagen deposition, which reduces injury. The choice linking slower growth, thicker walls, and injury resistance captures this central idea. The claim about aquaculture suitability extrapolates far beyond the passage, which describes a biological observation rather than aquaculture potential. The claim about predation pressure introduces a factor the passage never mentions; the passage discusses wave-induced lacerations, not predators. The claim that water temperature primarily drives collagen deposition contradicts Fujimura''s attribution of thickened walls to mechanical stress from wave action.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22YFXZ7', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The oversight board has insisted that each of the seventeen regional water authorities ______ an independent audit of its desalination infrastructure before the end of the fiscal year, a directive that several coastal districts have characterized as logistically impractical given current staffing shortages.', $lyceon_json$[{"key":"A","text":"undergo"},{"key":"B","text":"undergoes"},{"key":"C","text":"will undergo"},{"key":"D","text":"would undergo"}]$lyceon_json$::jsonb, 'A', NULL, E'The verb ''insisted'' triggers the mandative subjunctive in the ''that'' clause. In Standard English, verbs of insistence, demand, and requirement take the subjunctive mood, which uses the bare infinitive (base form) of the verb regardless of the subject''s number or person. Although ''each of the seventeen regional water authorities'' is grammatically singular and would ordinarily take the indicative ''undergoes,'' the subjunctive requires the uninflected base form ''undergo.'' The option ''undergoes'' incorrectly applies the indicative third-person singular inflection in a subjunctive context. The option ''will undergo'' improperly inserts a future-tense modal auxiliary into a subjunctive construction. The option ''would undergo'' introduces conditionality, suggesting the directive is hypothetical rather than issued, which contradicts the definitive meaning of ''has insisted.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23GAICT', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Cognitive scientist Hiroshi Fukuda has argued that bilingual speakers do not simply switch between two separate grammatical systems but instead maintain a single integrated network that activates elements of both languages simultaneously. Fukuda''s neuroimaging studies show overlapping activation patterns in the prefrontal cortex regardless of which language participants are using. ______ monolingual control subjects in the same studies show activation concentrated in a more limited region of the prefrontal cortex, a pattern Fukuda interprets as evidence that the broader activation in bilinguals reflects the integrated network rather than mere cognitive effort or task difficulty.', $lyceon_json$[{"key":"A","text":"Consequently,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"Crucially,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'C', NULL, E'The final sentence introduces the monolingual control comparison, which Fukuda treats as the key evidence distinguishing his integrated-network explanation from alternative explanations such as general cognitive effort. The transition "Crucially" correctly signals that this comparison is the decisive piece of evidence that strengthens the argument. The option "Consequently" implies the monolingual finding is a result of the bilingual activation pattern, but the two findings are parallel observations from the same study, not causally linked. The option "Similarly" suggests the monolingual pattern resembles the bilingual one, but the passage explicitly states the monolingual pattern is more limited, making it a contrast rather than a similarity. The option "For instance" implies the monolingual data is merely an example of the overlapping activation already described, but it is a contrasting data point used to rule out an alternative interpretation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23O87J8', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall purpose of the text?', E'In 1911, Harriet Quimby became the first American woman to earn a pilot''s license, and the following year she became the first woman to fly solo across the English Channel. Yet her Channel crossing, completed on April 16, 1912, received almost no press attention: the Titanic had sunk the previous day, and newspapers devoted their pages entirely to the maritime disaster. Quimby died in a flying accident just three months later, and without the publicity that her Channel flight should have generated, her contributions to early aviation were largely forgotten for decades.', $lyceon_json$[{"key":"A","text":"It explains how a coincidence of timing caused a pioneering aviator's achievement to be overshadowed and subsequently neglected by historical memory."},{"key":"B","text":"It compares the relative dangers of early aviation and transatlantic sea travel in the early 20th century."},{"key":"C","text":"It argues that Quimby's piloting skills were superior to those of her male contemporaries in early aviation."},{"key":"D","text":"It traces the technological developments that made solo Channel crossings by aircraft possible by 1912."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the causal chain linking the timing of the Titanic disaster to the press''s neglect of Quimby''s Channel crossing, and then connects that neglect to the subsequent forgetting of her contributions. This matches the option describing how a coincidence of timing caused her achievement to be overshadowed and forgotten. The option about comparing dangers of aviation and sea travel misreads the passage; the Titanic is mentioned only as a competing news event, not as a basis for comparing transportation risks. The option about Quimby''s superiority to male contemporaries introduces a claim the passage never makes; the text describes her pioneering achievements without ranking her against other pilots. The option about technological developments is unsupported; the passage focuses on Quimby''s accomplishments and their reception, not the engineering behind early aircraft.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW251A9TU', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a proposal for an urban studies course and wants to argue that converting vacant lots into community gardens produces measurable public health benefits beyond increased access to fresh produce. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
