INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW261LXP3', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Urban planner Sven Lindqvist analyzed pedestrian traffic data from 41 public plazas in mid-sized Swedish cities and found that plazas with at least one mature deciduous tree per 90 square meters of paved area attracted 57 percent more sustained foot traffic—defined as pedestrians remaining for 10 minutes or longer—than plazas with fewer trees or none at all. Lindqvist proposes that tree canopy shade reduces perceived thermal discomfort during summer months, making pedestrians more willing to linger. He notes, however, that the effect was pronounced only between May and September; during the colder months of October through March, tree density had no statistically significant relationship with sustained foot traffic. If Lindqvist''s interpretation is correct, one would expect that plazas with evergreen conifers providing year-round shade rather than deciduous trees ________', $lyceon_json$[{"key":"A","text":"would show a smaller seasonal difference in sustained foot traffic attributable to tree cover, since shade would be available in both warm and cold months."},{"key":"B","text":"would attract fewer pedestrians in summer because conifer needles provide less dense shade than broad deciduous leaves."},{"key":"C","text":"would have no effect on foot traffic in any season because pedestrians do not perceive conifer shade as comfortable."},{"key":"D","text":"would attract more sustained foot traffic than deciduous-tree plazas in every month of the year regardless of temperature."}]$lyceon_json$::jsonb, 'A', NULL, E'Lindqvist''s interpretation ties the foot-traffic benefit of trees specifically to shade reducing thermal discomfort during warm months, which explains why the effect disappears when deciduous trees lose their leaves in winter. Evergreen conifers providing year-round shade would logically narrow this seasonal gap, since shade would be present in both warm and cold months. The prediction that conifers would attract fewer summer pedestrians due to less dense shade introduces an assumption about needle versus leaf shade density that the passage does not support and that goes beyond the question of seasonal variation. The claim that conifer shade has no effect introduces an unsupported assumption about pedestrian perception of different shade types. The prediction that evergreen plazas would outperform in every month ignores Lindqvist''s finding that shade matters for thermal comfort, which implies the benefit depends on warmth; in cold months, shade may not increase comfort or could even decrease it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AA5ZFI', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After cataloging more than 1,400 nocturnal moth specimens from the cloud forests of southern ______ entomologist Dr. Rakesh Varma published a revised field guide that identified nineteen species previously unknown to science.', $lyceon_json$[{"key":"A","text":"Ecuador,"},{"key":"B","text":"Ecuador;"},{"key":"C","text":"Ecuador."},{"key":"D","text":"Ecuador:"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence opens with the introductory participial phrase ''After cataloging more than 1,400 nocturnal moth specimens from the cloud forests of southern Ecuador,'' which modifies the subject ''entomologist Dr. Rakesh Varma.'' A comma is the correct punctuation to separate an introductory modifying phrase from the main clause it modifies. A semicolon requires independent clauses on both sides, but the participial phrase is not an independent clause. A period would strand the participial phrase as a sentence fragment. A colon requires a complete independent clause before it, which the introductory phrase does not provide.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BUJRAB', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Amara Osei has shown that small-scale cassava farmers in Ghana''s Volta Region who adopted intercropping techniques between 2018 and 2023 experienced a 23 percent increase in annual yields per hectare. These gains, however, came at the cost of significantly more labor hours, a burden borne disproportionately by women in the households surveyed. ______ when Osei''s team analyzed net household income after accounting for the additional labor costs, the economic benefit of intercropping shrank to just 4 percent, a margin several farmers described as insufficient to justify the extra effort.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Indeed,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'B', NULL, E'The second sentence established that yield gains came with high labor costs; the third sentence reinforces and quantifies this problem by showing that net income gains were minimal once those costs were factored in. The transition "Indeed" correctly signals that the final sentence confirms and intensifies the concern raised in the preceding sentence. The option "Furthermore" implies the addition of a new, independent point, but the third sentence does not introduce a separate issue; it deepens the same concern about labor costs already raised. The option "Nevertheless" signals a concession or reversal, implying the third sentence would counteract the labor-cost concern, but instead it compounds it. The option "In other words" signals a restatement, yet the third sentence presents new quantitative analysis rather than rephrasing the prior claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CELGA3', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, which choice best describes how the author of Text 1 would most likely respond to the argument presented in Text 2?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DWQP3F', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an art history essay and wants to challenge the common view that Hilma af Klint''s abstract paintings were influenced by Wassily Kandinsky''s theories, using evidence that reframes the chronological relationship between the two artists'' work. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FF7YBP', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the restoration team, which included conservators from three national ______ had anticipated that the deteriorated pigments could be stabilized with a single application of the consolidant, a second treatment proved necessary after an unexpected cold front caused moisture to infiltrate the chapel''s north wall.', $lyceon_json$[{"key":"A","text":"museums, had anticipated"},{"key":"B","text":"museums had anticipated"},{"key":"C","text":"museums. Had anticipated"},{"key":"D","text":"museums; had anticipated"}]$lyceon_json$::jsonb, 'A', NULL, E'The nonrestrictive relative clause ''which included conservators from three national museums'' is inserted between the subject of the subordinate clause (''the restoration team'') and its verb (''had anticipated''). Because this relative clause opens with a comma before ''which,'' it must close with a comma after ''museums'' to properly delimit the parenthetical before the verb resumes. Dropping the closing comma leaves the nonrestrictive clause unresolved, obscuring the boundary between the parenthetical element and the predicate. A period after ''museums'' would fragment the sentence, severing the subordinate clause begun by ''Although'' from the rest of the sentence and leaving ''Had anticipated'' without a grammatical subject. A semicolon would similarly break the subordinate clause, separating the subject ''team'' from its verb ''had anticipated'' at an inappropriate structural point within a dependent clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HBRZS1', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a materials scientist, if accurate, would most effectively support the researchers'' claim?', E'A team of researchers at a Portuguese university claims that medieval Portuguese tilework, known as azulejo, achieves its distinctive resistance to salt crystallization damage not through the chemical composition of its glaze but through a network of microscopic pores in the ceramic body beneath the glaze. The researchers argue that these pores act as pressure-relief channels: when salt crystals form from moisture that has penetrated the tile, the pores distribute crystallization pressure across a large internal surface area, preventing the localized stress concentrations that cause spalling in less porous ceramics.', $lyceon_json$[{"key":"A","text":"\"Our micro-CT scans of seventeenth-century azulejo fragments reveal an interconnected pore network with an average channel diameter of 14 micrometers, which our finite-element models predict would reduce peak crystallization stress by 63 percent compared to a non-porous ceramic of identical composition.\""},{"key":"B","text":"\"The lead-tin glazes used in Portuguese azulejo production between 1580 and 1720 contain antimony concentrations significantly higher than those found in contemporary Spanish majolica glazes.\""},{"key":"C","text":"\"Azulejo tiles exported to colonial Brazil in the eighteenth century were frequently damaged during transatlantic shipping, suggesting that their durability has been overstated by architectural historians.\""},{"key":"D","text":"\"Modern industrial ceramic tiles fired at temperatures above 1200 degrees Celsius are substantially harder than traditional azulejo, which was typically fired between 950 and 1050 degrees Celsius.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers claim that microscopic pores in the ceramic body distribute crystallization pressure to prevent damage. The quotation describing micro-CT evidence of an interconnected pore network and finite-element modeling showing a 63 percent reduction in peak crystallization stress directly supports both the existence of the pore network and its pressure-relieving function. The quotation about antimony concentrations in the glaze addresses glaze chemistry, which the researchers explicitly distinguish from the pore-based mechanism they propose. The quotation about shipping damage to exported tiles concerns a different type of damage unrelated to salt crystallization resistance and actually contradicts claims of durability. The quotation about firing temperatures and hardness compares modern and traditional ceramics on a property the passage does not connect to salt crystallization resistance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HDMIJM', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IIM7BH', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economist Nadia Borovik studied the adoption of mobile payment platforms among street vendors in 14 cities across East Africa and found that vendors who switched from cash-only transactions to mobile payments experienced a 19 percent increase in daily revenue within the first six months. Borovik attributes this increase primarily to an expansion of each vendor''s customer base: customers carrying no physical cash could now make purchases they would otherwise have forgone. However, Borovik also observed that vendors who adopted mobile payments reported spending an average of 53 minutes per day managing transaction records, resolving payment disputes, and troubleshooting connectivity issues—time previously spent serving customers. Borovik suggests that if the administrative burden of mobile payments could be reduced, the revenue gains from expanded customer access would be even larger. To strengthen this suggestion, Borovik would need to show that ________', $lyceon_json$[{"key":"A","text":"vendors who used mobile payment platforms with streamlined interfaces and fewer connectivity disruptions captured revenue gains exceeding 19 percent, indicating that reduced administrative burden unlocks additional sales."},{"key":"B","text":"the 19 percent revenue increase was consistent across all 14 cities regardless of differences in smartphone ownership rates."},{"key":"C","text":"vendors who continued accepting only cash maintained stable revenues throughout the study period."},{"key":"D","text":"mobile payment platform fees consumed less than 5 percent of the vendors' increased revenue."}]$lyceon_json$::jsonb, 'A', NULL, E'Borovik''s suggestion is that reducing administrative burden would amplify the revenue benefit of mobile payments. To strengthen this, she would need evidence that vendors experiencing lower administrative friction achieved greater revenue gains than the 19 percent observed under current conditions, directly demonstrating that reduced burden translates to additional sales. The finding about consistent gains across cities addresses geographic generalizability but does not test whether reducing the administrative burden specifically increases revenue beyond 19 percent. The finding about stable cash-only revenues establishes a baseline but does not address the relationship between administrative burden and revenue gains from mobile payments. The finding about platform fees addresses profitability rather than the specific claim that time lost to administrative tasks suppresses potential revenue growth.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IPA2QD', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The municipal archivist discovered that seventeen handwritten ledgers from the 1830s, which had been stored in an unventilated basement beneath the old ______ contained detailed census records that contradicted the town''s accepted founding date by nearly forty years.', $lyceon_json$[{"key":"A","text":"courthouse, contained"},{"key":"B","text":"courthouse contained"},{"key":"C","text":"courthouse; contained"},{"key":"D","text":"courthouse. They contained"}]$lyceon_json$::jsonb, 'A', NULL, E'The nonrestrictive relative clause ''which had been stored in an unventilated basement beneath the old courthouse'' provides additional information about ''seventeen handwritten ledgers.'' Because the clause opens with a comma before ''which,'' it must close with a comma after ''courthouse'' to properly set off the parenthetical element before the main clause continues with ''contained.'' Omitting the closing comma leaves the nonrestrictive clause unresolved, creating ambiguity about where the parenthetical ends and the verb begins. A semicolon would incorrectly sever the subject ''ledgers'' from its predicate ''contained,'' splitting one clause into two fragments. A period followed by ''They contained'' would similarly break the main clause, separating the subject from its verb and producing a sentence whose first half ends with an unresolved relative clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KJ24CH', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The medieval fortress, originally constructed in 1247 to defend the alpine trade route connecting Innsbruck to Bolzano, ______ extensively during the Napoleonic Wars and again during a series of border disputes in the 1860s before being converted into a regional history museum in 1923.', $lyceon_json$[{"key":"A","text":"was damaged"},{"key":"B","text":"has been damaged"},{"key":"C","text":"had been damaged"},{"key":"D","text":"is damaged"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence narrates a sequence of completed historical events anchored in specific past time periods (the Napoleonic Wars, the 1860s, 1923). The simple past passive ''was damaged'' correctly places the action in a completed past context and coordinates with the subsequent past-tense verbs in the series (''being converted''). The present perfect ''has been damaged'' incorrectly links past events to the present moment, which is inappropriate for a narrative entirely set in defined historical periods. The past perfect ''had been damaged'' would require a later past reference point from which to look further back, but the sentence does not establish such a two-layer past sequence; instead, it presents events chronologically. The present tense ''is damaged'' is entirely inconsistent with the historical context of the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LQ9YUF', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Archaeologist Miriam Boulos has proposed a reinterpretation of Bronze Age grain storage pits excavated at a hillfort site in southern Lebanon. Earlier excavators classified these pits as household pantries belonging to individual family units, based on their small size and distribution among residential structures. Boulos, however, analyzed residues from 67 pits and found that each pit contained grain from at least three distinct wheat varieties originating in different microclimatic zones within a 40-kilometer radius. She argues that the mixing of grain from multiple ecological zones indicates a communal pooling strategy rather than household-level storage: families contributed portions of their harvests to shared reserves, diversifying the collective food supply against localized crop failures. Boulos notes that this pooling model aligns with evidence of coordinated terrace construction across the hillfort''s agricultural hinterland.', $lyceon_json$[{"key":"A","text":"Bronze Age grain pits at a Lebanese hillfort contained mixed grain varieties from different zones, suggesting communal pooling rather than individual household storage."},{"key":"B","text":"Wheat cultivation in Bronze Age Lebanon was more technologically advanced than scholars had previously believed."},{"key":"C","text":"The hillfort's residential structures were organized around extended kinship groups rather than nuclear families."},{"key":"D","text":"Residue analysis is a more reliable archaeological method than the spatial mapping techniques used by earlier excavators."}]$lyceon_json$::jsonb, 'A', NULL, E'Boulos''s central argument is that the presence of multiple wheat varieties from different microclimatic zones in each pit points to communal grain pooling as a risk-diversification strategy, overturning the earlier household-pantry interpretation. The choice about mixed grain varieties indicating communal pooling captures this reinterpretation. The claim about advanced wheat cultivation technology goes beyond the passage, which discusses storage practices rather than agricultural technology. The assertion about kinship-based residential organization introduces a social structure claim the passage never makes; Boulos''s argument concerns storage strategy, not household composition. The claim about residue analysis being more reliable than spatial mapping focuses on a methodological comparison the passage does not explicitly make; Boulos uses residue analysis as evidence for her argument but does not rank it against other methods.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M7WVQX', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Agricultural scientist Farah Mehdaoui studied pollination rates in apricot orchards across northeastern Tunisia and found that orchards bordered by strips of wild rosemary and lavender attracted 3.4 times as many native solitary bees as orchards surrounded by bare fallow land. The orchards with wildflower borders also produced 23 percent more fruit per tree. Mehdaoui attributes the higher fruit yield to increased pollination by the solitary bees drawn to the flowering border plants. Based on Mehdaoui''s findings, an apricot grower who converted bare fallow borders to wildflower strips would most likely observe that ________', $lyceon_json$[{"key":"A","text":"more solitary bees visit the orchard and fruit production per tree increases."},{"key":"B","text":"the apricot trees flower earlier in the season due to the proximity of flowering plants."},{"key":"C","text":"soil nutrient levels in the orchard decline because the wildflower strips compete for resources."},{"key":"D","text":"fruit yield remains unchanged because commercial honeybees are more effective pollinators than solitary bees."}]$lyceon_json$::jsonb, 'A', NULL, E'Mehdaoui''s research directly connects wildflower borders to greater solitary bee visitation and higher fruit yields. Converting bare borders to wildflower strips would logically replicate these results. The prediction about earlier flowering introduces a phenological effect the passage never discusses; the border plants attract bees but are not described as influencing tree flowering time. The prediction about declining soil nutrients introduces a resource-competition concern not mentioned or implied in the passage. The prediction that yield would remain unchanged because honeybees are superior contradicts Mehdaoui''s finding that solitary bees attracted by wildflower borders meaningfully increased fruit production.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NDCG42', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The Venus flytrap captures insects using a pair of hinged lobes lined with trigger hairs. [underlined: When a visiting ant brushes against two of these hairs within approximately twenty seconds, the lobes snap shut in less than one-tenth of a second, trapping the insect inside a sealed digestive chamber.] The plant then secretes enzymes that dissolve the soft tissues of the prey over a period of five to twelve days.', $lyceon_json$[{"key":"A","text":"It describes the specific mechanism by which the trap is activated, explaining both the trigger condition and the speed of closure."},{"key":"B","text":"It provides a historical account of how scientists first observed the Venus flytrap's predatory behavior."},{"key":"C","text":"It argues that the Venus flytrap is more efficient at capturing prey than other carnivorous plants."},{"key":"D","text":"It qualifies the opening claim by noting that the trapping mechanism does not always function as described."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence explains two specific details about how the trap works: the trigger condition (two hairs brushed within twenty seconds) and the response speed (closure in less than one-tenth of a second). This directly elaborates on the opening sentence''s general claim about the hinged-lobe trapping mechanism. The option about a historical account of scientific observation is unsupported; the sentence describes a biological mechanism, not a discovery narrative. The option about comparative efficiency introduces a claim the passage never makes; no other carnivorous plants are mentioned. The option about qualifying the opening claim contradicts the passage; the underlined sentence reinforces rather than limits the trapping description.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NZORUS', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central claim of the text?', E'Neuroscientist Haruto Kimura has challenged the dominant model of how the brain processes musical dissonance. The prevailing view holds that dissonance perception arises from interference patterns between closely spaced frequencies in the cochlea, making it essentially a peripheral auditory phenomenon. Kimura''s experiments, however, used artificially generated tones that eliminated cochlear interference by presenting each frequency to a separate ear through headphones. Listeners still reported strong dissonance ratings for frequency combinations traditionally considered dissonant, even though no interference could occur in either cochlea. Kimura argues that these results indicate a central neural mechanism—likely in the auditory cortex—that evaluates frequency ratios independently of peripheral beating. He concedes that cochlear interference may amplify the sensation of dissonance under normal listening conditions but maintains that it cannot be the originating source, since dissonance persists in its complete absence.', $lyceon_json$[{"key":"A","text":"Dissonance perception originates in central neural processing of frequency ratios rather than in cochlear interference, though cochlear effects may intensify the experience."},{"key":"B","text":"The auditory cortex processes musical consonance and dissonance through entirely separate neural pathways."},{"key":"C","text":"Cochlear interference has no measurable effect on how listeners perceive dissonant musical intervals."},{"key":"D","text":"Presenting tones to separate ears through headphones eliminates all perceptual differences between consonant and dissonant intervals."}]$lyceon_json$::jsonb, 'A', NULL, E'Kimura''s central claim is that dissonance perception originates in a central neural mechanism evaluating frequency ratios, not in cochlear interference, while acknowledging that cochlear effects may amplify the sensation under normal conditions. The choice attributing dissonance to central neural processing while noting cochlear amplification captures both aspects of this claim. The assertion about entirely separate neural pathways for consonance and dissonance introduces a structural distinction the passage never discusses; Kimura identifies the auditory cortex as a likely location but makes no claims about separate pathways. The claim that cochlear interference has no measurable effect contradicts Kimura''s own concession that it may amplify dissonance under normal listening conditions. The claim that headphone presentation eliminates all perceptual differences misrepresents the experiment: listeners still perceived dissonance through headphones, which was the key finding supporting Kimura''s argument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QNV771', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The geophysicist''s predictive model—calibrated using seismic wave data from twenty-three monitoring stations distributed along the volcanic arc of the Lesser ______ proved remarkably accurate when a magnitude 5.7 earthquake struck the region eleven days after her initial forecast.', $lyceon_json$[{"key":"A","text":"Antilles—proved"},{"key":"B","text":"Antilles, proved"},{"key":"C","text":"Antilles; proved"},{"key":"D","text":"Antilles proved"}]$lyceon_json$::jsonb, 'A', NULL, E'The parenthetical element ''calibrated using seismic wave data from twenty-three monitoring stations distributed along the volcanic arc of the Lesser Antilles'' is opened with a dash after ''model.'' Punctuation symmetry in Standard English requires a matching dash after ''Antilles'' to close the parenthetical before the predicate ''proved.'' A comma after ''Antilles'' creates a mismatched punctuation pair (dash-open, comma-close), which violates standard conventions. A semicolon would incorrectly separate the subject ''model'' from its predicate ''proved,'' splitting the main clause. Omitting all punctuation after ''Antilles'' leaves the parenthetical unresolved, merging it into the predicate without any boundary marker.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QOIAMH', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'When the ceramic restorer examined the 14th-century bowl, she found that previous repairs using modern adhesive had actually ______ the original glazework, leaving cloudy residues that obscured the intricate floral patterns beneath.', $lyceon_json$[{"key":"A","text":"marred"},{"key":"B","text":"cataloged"},{"key":"C","text":"circulated"},{"key":"D","text":"postponed"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that adhesive repairs left cloudy residues that obscured floral patterns, indicating the repairs damaged or spoiled the original glazework. The word meaning to damage or spoil the appearance of something fits this context precisely. The word meaning to systematically record items in a list describes an archival action unrelated to the physical damage described. The word meaning to move or pass around describes distribution, which has no connection to the adhesive''s effect on the bowl''s surface. The word meaning to delay to a later time describes deferral, which does not describe the physical impairment caused by the adhesive residues.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U8R4BL', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the final sentence in the text?', E'Geochemist Elena Zharkova''s analysis of zircon crystals from the Jack Hills formation in Western Australia pushed the estimated age of Earth''s earliest continental crust back to 4.37 billion years — only 150 million years after the planet''s formation. This finding challenged the prevailing model in which Earth''s surface remained molten for at least 500 million years, a period geologists informally called the Hadean ''magma ocean'' phase. Zharkova''s zircons, however, contained oxygen isotope signatures consistent with the presence of liquid water, suggesting that portions of the surface had cooled enough for hydrological cycling far earlier than the magma ocean model permits. If this interpretation withstands scrutiny, the window during which conditions hospitable to prebiotic chemistry could have existed on Earth widens by several hundred million years.', $lyceon_json$[{"key":"A","text":"It articulates a broader implication of Zharkova's findings by connecting the earlier surface cooling to the timeframe available for the emergence of life's chemical precursors."},{"key":"B","text":"It concedes that Zharkova's evidence is insufficient to overturn the magma ocean model without additional corroborating studies."},{"key":"C","text":"It shifts the focus from geology to biology by describing specific prebiotic organisms that may have existed during the Hadean period."},{"key":"D","text":"It restates the central claim about zircon dating in simpler terms to ensure the reader understands the preceding technical argument."}]$lyceon_json$::jsonb, 'A', NULL, E'The final sentence extends the geological finding about earlier surface cooling to a new domain: the timeline for prebiotic chemistry. By stating that the window for hospitable conditions widens by several hundred million years, it identifies a significant consequence of Zharkova''s work beyond geology. The option about conceding insufficient evidence misreads the conditional phrasing; ''if this interpretation withstands scrutiny'' signals caution about the interpretation, not an admission that the evidence is inadequate. The option about shifting to describe specific organisms overstates the sentence''s scope; it references prebiotic chemistry as a general possibility, not specific organisms. The option about restating the central claim in simpler terms mischaracterizes the sentence''s function; it introduces a new implication rather than rephrasing the zircon dating argument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V7V6ZJ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Suspended from a network of titanium cables anchored to the canyon walls at an elevation of 890 ______ an observation platform and a climate-monitoring station that the national park service commissioned in 2021 to track atmospheric particulate levels across the gorge.', $lyceon_json$[{"key":"A","text":"meters hang"},{"key":"B","text":"meters hangs"},{"key":"C","text":"meters, hanging"},{"key":"D","text":"meters are hanging"}]$lyceon_json$::jsonb, 'A', NULL, E'This sentence uses inverted word order: the participial phrase ''Suspended from a network of titanium cables anchored to the canyon walls at an elevation of 890 meters'' precedes the verb, and the compound subject ''an observation platform and a climate-monitoring station'' follows it. Because the subject is compound (two items joined by ''and''), the verb must be plural. The plural present-tense ''hang'' correctly agrees with the compound subject and conveys the ongoing state of the structures being suspended. The singular ''hangs'' fails to agree with the compound subject. The participial form ''hanging'' preceded by a comma produces a fragment, since it provides no finite verb for the compound subject. The progressive ''are hanging'' uses the correct plural number but implies a temporary or in-progress action, which is inappropriate for permanently installed structures; the simple present is needed to describe their fixed state.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VDC2PD', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support Okonkwo''s hypothesis?', E'Ecologist Chidera Okonkwo hypothesizes that the unusually high density of termite mounds in a savanna region of central Mozambique is driven by the clay-rich composition of the local soil, which provides superior structural material for mound construction. Okonkwo notes that neighboring savannas with sandier soils support termite mound densities roughly one-third as high, despite hosting the same termite species and receiving comparable rainfall.', $lyceon_json$[{"key":"A","text":"When clay was experimentally added to sandy soils in a controlled field plot, the same termite species built 2.6 times as many mounds as in unmodified sandy plots."},{"key":"B","text":"Termite species in tropical forests construct mounds primarily from chewed wood pulp rather than soil particles."},{"key":"C","text":"Average annual rainfall in central Mozambique has decreased by 11 percent over the past two decades."},{"key":"D","text":"The central Mozambique savanna supports a higher diversity of grass species than the neighboring sandy savannas."}]$lyceon_json$::jsonb, 'A', NULL, E'Okonkwo''s hypothesis is that clay-rich soil drives higher termite mound density by providing better construction material. An experiment showing that adding clay to sandy soil causes the same termite species to build significantly more mounds directly isolates clay content as the causal factor. The finding about forest termites using wood pulp concerns a different habitat and construction material entirely unrelated to the savanna soil-composition hypothesis. The finding about declining rainfall introduces a climate variable that does not address whether soil clay content determines mound density. The finding about grass species diversity describes a vegetation difference that does not explain why termites build more mounds in clay-rich soil.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WK67HX', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the lead violinist nor the two cellists in the chamber ensemble ______ willing to perform the experimental composition without at least three additional rehearsals.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"were"},{"key":"C","text":"has been"},{"key":"D","text":"is"}]$lyceon_json$::jsonb, 'B', NULL, E'In a ''neither...nor'' construction, the verb agrees with the subject closest to it. Because ''the two cellists'' is plural and appears nearest to the verb, the plural form ''were'' is required. The singular ''was'' would incorrectly agree with the more distant singular subject ''the lead violinist'' rather than the nearer plural subject. The singular ''has been'' commits the same agreement error while also introducing the present perfect tense, which conflicts with the past-tense context of the passage. The singular present-tense ''is'' both violates the proximity agreement rule and introduces a tense inconsistency.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WT3R9U', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Although the municipal council had initially dismissed the proposal to convert abandoned rail corridors into cycling paths, growing evidence of reduced traffic congestion in cities that adopted similar projects eventually ______ the council''s resistance, leading to a unanimous vote in favor of the plan.', $lyceon_json$[{"key":"A","text":"eroded"},{"key":"B","text":"fabricated"},{"key":"C","text":"quarantined"},{"key":"D","text":"indexed"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a gradual process in which accumulating evidence wore down the council''s initial opposition until they unanimously approved the plan. The word meaning to gradually wear away or diminish captures this progressive weakening of resistance. The word meaning to construct or invent something, often with a connotation of deception, does not describe the diminishment of opposition. The word meaning to isolate to prevent the spread of disease describes a containment action that has no relevance to the council''s changing position. The word meaning to organize information into a systematic list describes cataloguing, which does not convey the gradual breaking down of resistance described in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YOMB7F', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding would most directly undermine the explanation offered by Pettersson and Dhawan?', E'Glaciologists Pettersson and Dhawan investigated why a particular glacier in Svalbard surges forward unpredictably every 37 to 43 years while neighboring glaciers of similar size flow at steady rates. They propose that a layer of clay-rich sediment beneath the glacier acts as a water-sealed barrier: over decades, meltwater slowly accumulates above the clay layer until hydrostatic pressure lifts the glacier off its bed, triggering a rapid surge. They support this explanation by noting that borehole measurements taken two years before the most recent surge showed water pressure at the glacier base was 94 percent of the ice overburden pressure, far above the 60 to 70 percent typical of the stable neighboring glaciers.', $lyceon_json$[{"key":"A","text":"Seismic surveys revealed that the surging glacier and its stable neighbors all rest on clay-rich sediment layers of comparable thickness and impermeability."},{"key":"B","text":"The surging glacier's surface temperature during winter was 1.8 degrees Celsius colder than that of the neighboring glaciers."},{"key":"C","text":"Satellite imagery confirmed that the glacier's most recent surge advanced the terminus by 2.9 kilometers over 14 months."},{"key":"D","text":"Borehole measurements in the neighboring glaciers showed water pressure fluctuations correlated with seasonal meltwater input."}]$lyceon_json$::jsonb, 'A', NULL, E'Pettersson and Dhawan''s explanation depends on the clay-rich sediment layer being a distinguishing feature of the surging glacier. If the stable neighboring glaciers also rest on equally thick and impermeable clay layers yet do not surge, then the clay barrier alone cannot explain why only this glacier surges, directly undermining their proposed mechanism. The finding about colder surface temperatures introduces a variable the passage does not connect to the basal water-pressure mechanism and does not challenge the clay-layer explanation. The confirmation of surge distance and duration describes the surge itself but does not address whether the clay-layer mechanism causes it. The finding about seasonal pressure fluctuations in neighboring glaciers describes normal hydrological behavior that does not challenge the claim that the surging glacier''s clay layer uniquely traps water to abnormally high pressure.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
