INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZQ1836', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Entomologist Priya Bhattacharya has observed that colonies of the carpenter ant Camponotus floridanus adjust their foraging schedules in response to ambient temperature fluctuations, shifting activity to cooler nighttime hours during summer heat waves. ______ Bhattacharya suggests that the species may be more resilient to rising temperatures than previously assumed.', $lyceon_json$[{"key":"A","text":"For this reason,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence draws a conclusion about the species'' resilience that follows directly from the behavioral adaptation described in the first sentence. The transition "For this reason" correctly signals that the conclusion is grounded in the preceding evidence. The option suggesting contrast ("In contrast") implies an opposition between the two sentences, but no opposing claim is introduced. The option "Specifically" would indicate the second sentence narrows or exemplifies the first, yet a broad suggestion about resilience does not serve as a specific instance of schedule adjustment. The option "Meanwhile" implies two concurrent but independent events, but the second sentence is a logical inference from the first, not a simultaneous occurrence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
